import { cn } from "../shared/utils";
import { useReducedMotion } from "motion/react";
import {
  type KeyboardEvent,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";

export type GravityLettersTrigger = "click" | "hover" | "inView" | "manual";

export interface GravityLettersProps {
  bounce?: number;
  className?: string;
  collapsed?: boolean;
  friction?: number;
  gravity?: number;
  onCollapsedChange?: (collapsed: boolean) => void;
  spread?: number;
  stagger?: number;
  text: string;
  trigger?: GravityLettersTrigger;
}

interface LetterOrigin {
  height: number;
  width: number;
  x: number;
  y: number;
}

interface LetterPhysics {
  angle: number;
  angularVel: number;
  dx: number;
  dy: number;
  releaseAt: number;
  settled: boolean;
  vx: number;
  vy: number;
}

